create or replace function public.commit_ingestion_batch(p_id uuid,p_token uuid,p_jobs jsonb) returns integer language plpgsql security definer set search_path='' as $$ declare task public.ingestion_tasks%rowtype; board_row public.job_boards%rowtype; n integer; begin if jsonb_typeof(p_jobs) is distinct from 'array' or jsonb_array_length(p_jobs)>100 then raise exception 'Invalid batch'; end if; select * into task from public.ingestion_tasks where id=p_id and status='running' and lease_token=p_token for update; if not found or task.lease_until is null or task.lease_until<=clock_timestamp() then raise exception 'Lease lost'; end if; select * into board_row from public.job_boards where id=task.board_id and enabled; if not found then raise exception 'Board disabled'; end if; if exists(select 1 from jsonb_array_elements(p_jobs) j where jsonb_typeof(j) is distinct from 'object' or j->>'source' is distinct from board_row.source or left(coalesce(j->>'source_id',''),length(board_row.board)+1)<>board_row.board||':' or length(coalesce(j->>'source_id',''))>4096 or length(coalesce(j->>'title','')) not between 1 and 500 or length(coalesce(j->>'company','')) not between 1 and 200 or length(coalesce(j->>'location',''))>1000 or length(coalesce(j->>'description',''))>1000000 or coalesce(j->>'listing_url','') !~ '^https://') then raise exception 'Invalid listing'; end if; insert into public.jobs(source,source_id,title,company,location,description,listing_url,published_at,last_verified_at,active) select source,source_id,title,company,coalesce(location,''),coalesce(description,''),listing_url,published_at,last_verified_at,true from jsonb_to_recordset(p_jobs) as x(source text,source_id text,title text,company text,location text,description text,listing_url text,published_at timestamptz,last_verified_at timestamptz) on conflict(source,source_id) do update set title=excluded.title,company=excluded.company,location=excluded.location,description=excluded.description,listing_url=excluded.listing_url,published_at=excluded.published_at,last_verified_at=excluded.last_verified_at,active=true; get diagnostics n=row_count; return n; end $$;
create or replace function public.finish_ingestion_task(p_id uuid,p_token uuid,p_success boolean,p_count integer,p_error text) returns boolean language plpgsql security definer set search_path='' as $$ declare t public.ingestion_tasks%rowtype; begin select * into t from public.ingestion_tasks where id=p_id and status='running' and lease_token=p_token for update; if not found or t.lease_until is null or t.lease_until<=clock_timestamp() then return false; end if; if p_success then update public.ingestion_tasks set status='succeeded',finished_at=now(),imported_count=greatest(0,p_count),last_error=null,lease_token=null,lease_until=null where id=p_id; elsif t.attempts>=3 then update public.ingestion_tasks set status='failed',finished_at=now(),last_error=left(coalesce(p_error,'Ingestion failed'),200),lease_token=null,lease_until=null where id=p_id; else update public.ingestion_tasks set status='queued',available_at=now()+make_interval(mins=>t.attempts*5),last_error=left(coalesce(p_error,'Ingestion failed'),200),lease_token=null,lease_until=null where id=p_id; end if; return true; end $$;
